<template>
  <div class="friends-backdrop" @mousedown.stop @click.self="$emit('close')" @keydown.esc.stop.prevent="closeOrBack" @keydown.tab="trapFocus">
    <section ref="panel" class="friends-panel" role="dialog" aria-modal="true" aria-labelledby="friends-title">
      <header><div><small>CARNET DES DRESSEURS</small><h2 id="friends-title">Amis <span>{{ state.accepted.filter(p=>p.online).length }} en ligne</span></h2></div><button ref="close" data-gamepad-back aria-label="Fermer les amis" @click="$emit('close')">×</button></header>
      <p v-if="!connected" class="friends-notice" role="status">Connexion interrompue. Les actions reprendront à la reconnexion.</p>
      <p v-if="error || serverError" class="friends-error" role="alert">{{ error || serverError }}</p><p v-if="notice" class="friends-notice" role="status">{{ notice }}</p>
      <div v-if="tradeInvite" class="friend-trade-invite" data-friend-trade-invite><p><strong>{{ tradeInvite.participants.find(p=>p.id===tradeInvite.requestedBy)?.username || 'Un ami' }}</strong> te propose un échange en Aventure.</p><button data-trade-accept :disabled="trading || !connected || !canTrade" @click="$emit('trade-answer',true)">Accepter l’échange</button><button data-trade-decline :disabled="trading || !connected" @click="$emit('trade-answer',false)">Refuser</button><small v-if="!canTrade">Reviens en Aventure pour échanger.</small></div>
      <nav class="friends-tabs" aria-label="Carnet"><button :aria-pressed="tab==='friends'" data-social-tab="friends" @click="changeTab('friends')"><span>Tes amis</span><small v-if="incomingCount">{{ incomingCount }}</small></button><button :aria-pressed="tab==='online'" data-social-tab="online" @click="changeTab('online')"><span>Dresseurs connectés</span></button><button :aria-pressed="tab==='group'" data-social-tab="group" @click="changeTab('group')"><span>Groupe</span><small v-if="state.groupInvites.length">{{ state.groupInvites.length }}</small></button></nav>
      <div v-if="tab!=='group'" class="friends-layout" :class="{'has-conversation':!!selected}">
        <aside class="friends-directory">
          <template v-if="tab==='friends'">
            <h3>Tes amis <small>{{ state.accepted.length }}</small></h3><button v-for="p in sortedFriends" :key="p.id" :data-social-friend="p.id" class="friend-row" :class="{selected:selected?.id===p.id}" @click="selectTrainer(p)"><span class="friend-dot" :class="{online:connected&&p.online}"></span><span><strong>{{ p.username }}</strong><small>{{ connected&&p.online?'Connecté':'Hors ligne' }}</small></span><b v-if="p.unread" class="friend-unread">{{ p.unread>99?'99+':p.unread }}</b></button>
            <p v-if="!state.accepted.length" class="friends-empty">Retrouve les dresseurs que tu rencontres dans l’onglet Dresseurs connectés.</p>
            <button v-if="!state.accepted.length" class="directory-more" data-social-discover @click="changeTab('online')">Trouver des dresseurs</button>
            <h3 v-if="state.incoming.length">Demandes reçues</h3><div v-for="p in state.incoming" :key="'in-'+p.id" class="friend-entry friend-request"><strong>{{ p.username }}</strong><div><button :data-social-accept="p.id" :disabled="busy || !connected" @click="friendAction(p.id,'accept')">Accepter</button><button :disabled="busy || !connected" @click="friendAction(p.id,'decline')">Refuser</button></div></div>
            <h3 v-if="state.outgoing.length">Demandes envoyées</h3><div v-for="p in state.outgoing" :key="'out-'+p.id" class="friend-entry"><strong>{{ p.username }}</strong><button :disabled="busy || !connected" @click="friendAction(p.id,'cancel')">Annuler</button></div>
          </template>
          <template v-else>
          <label>Chercher un dresseur<input v-model="query" data-social-search type="search" maxlength="50" placeholder="Pseudo · 2 caractères minimum" :disabled="!connected" @input="scheduleSearch" /></label>
          <div v-if="searching" class="friends-empty" role="status">Recherche…</div>
          <template v-if="query.trim().length>=2"><p v-if="!searching&&!results.length" class="friends-empty">Aucun dresseur trouvé.</p><div v-for="p in results" :key="'search-'+p.id" class="friend-entry" :data-social-result="p.id"><button class="friend-name" @click="selectTrainer(p)"><span class="friend-dot" :class="{online:connected&&p.online}"></span><span>{{ p.username }}<small>{{ connected&&p.online?'Connecté':'Hors ligne' }}</small></span></button><button v-if="relation(p.id)==='none'" :disabled="busy || !connected" :data-social-search-add="p.id" @click="friendAction(p.id,'request')">Ajouter</button><button v-else-if="relation(p.id)==='incoming'" :disabled="busy || !connected" :data-social-search-accept="p.id" @click="friendAction(p.id,'accept')">Accepter</button><small v-else>{{ relationshipLabel(relation(p.id)) }}</small></div><button v-if="searchMore" class="directory-more" data-social-search-more :disabled="searching||!connected" @click="loadMoreSearch">{{ searching?'Recherche…':'Afficher plus' }}</button></template>
            <section v-else class="online-directory" aria-labelledby="online-directory-title" :aria-busy="onlineLoading">
              <h3 id="online-directory-title">Dresseurs connectés <small v-if="connected">{{ onlineTotal }}</small></h3>
              <p class="directory-hint">Dans tous les modes</p>
              <p v-if="onlineLoading&&!onlineEntries.length" class="friends-empty" role="status">Chargement des dresseurs…</p>
              <p v-else-if="connected&&!onlineEntries.length" class="friends-empty">Aucun autre dresseur connecté pour le moment.</p>
              <div v-for="p in onlineEntries" :key="'online-'+p.id" class="friend-entry" :data-social-online="p.id">
                <button class="friend-name" @click="selectTrainer(p)"><span class="friend-dot online"></span><span>{{ p.username }}<small>Connecté</small></span></button>
                <button v-if="relation(p.id)==='none'" :data-social-online-add="p.id" :disabled="busy||!connected" @click="friendAction(p.id,'request')">Ajouter</button>
                <button v-else-if="relation(p.id)==='incoming'" :data-social-online-accept="p.id" :disabled="busy||!connected" @click="friendAction(p.id,'accept')">Accepter</button>
                <small v-else>{{ relationshipLabel(relation(p.id)) }}</small>
              </div>
              <button v-if="onlineMore" class="directory-more" data-social-online-more :disabled="onlineLoading||!connected" @click="loadOnline(true)">{{ onlineLoading?'Chargement…':'Afficher plus' }}</button>
            </section>
          </template>
        </aside>
        <main class="friend-conversation">
          <template v-if="selected">
            <div class="conversation-heading"><button class="friends-back" data-social-back @click="selected=null">{{ tab==='online'?'‹ Dresseurs':'‹ Amis' }}</button><div><h3>{{ selected.username }}</h3><small>{{ selectedOnline?'Connecté':'Hors ligne' }}</small></div><button v-if="relation(selected.id)==='friends' && selectedFriend?.online" data-friend-trade :disabled="busy || trading || !connected || !canTrade" @click="askTrade">Échanger</button><button v-if="relation(selected.id)==='friends' && selectedFriend?.online" data-social-invite :disabled="busy || !connected || !!state.group && state.group.leaderId!==userId || state.group?.members.some(m=>m.id===selected.id)" @click="invite(selected.id)">Inviter au groupe</button></div>
            <template v-if="relation(selected.id)==='friends'">
              <div ref="messages" class="conversation-messages" role="log" aria-label="Messages privés" aria-live="polite"><button v-if="before" class="older-messages" :disabled="loadingMessages" @click="loadHistory(true)">Messages précédents</button><p v-if="loadingMessages" class="friends-empty" role="status">Chargement…</p><p v-if="!loadingMessages&&!messages.length" class="friends-empty">Commence la conversation. Les messages restent disponibles hors connexion.</p><article v-for="m in messages" :key="m.id" :data-social-message="m.id" :class="{mine:m.senderId===userId}"><small>{{ m.senderId===userId?'Toi':selected.username }} · {{ time(m.createdAt) }}</small><p>{{ m.text }}</p></article></div>
              <form class="conversation-compose" @submit.prevent="send"><label class="sr-only" for="friend-message">Message pour {{ selected.username }}</label><textarea id="friend-message" v-model="draft" data-social-draft rows="2" maxlength="500" placeholder="Écris un message…" :disabled="!connected || sending" @keydown.enter.exact.prevent="send"></textarea><button data-social-send :disabled="!connected || sending || !draft.trim()">{{ sending?'Envoi…':'Envoyer' }}</button></form>
              <button class="friend-remove" data-social-remove :disabled="busy || !connected" @click="removeConfirmation=true">Retirer cet ami</button>
              <div v-if="removeConfirmation" class="friends-confirm" role="alertdialog" aria-label="Retirer cet ami"><p>Retirer {{ selected.username }} de tes amis ?</p><button @click="removeConfirmation=false">Garder cet ami</button><button :disabled="busy" @click="friendAction(selected.id,'remove')">Retirer</button></div>
            </template>
            <div v-else class="friends-empty"><p>{{ relationshipLabel(relation(selected.id)) }}</p><button v-if="relation(selected.id)==='none'" :disabled="busy || !connected" :data-social-add="selected.id" @click="friendAction(selected.id,'request')">Ajouter en ami</button><button v-else-if="relation(selected.id)==='incoming'" :disabled="busy || !connected" @click="friendAction(selected.id,'accept')">Accepter la demande</button></div>
          </template>
          <div v-else class="friends-welcome"><journal-icon name="friends" aria-hidden="true"/><h3>Garde le contact</h3><p>Choisis un ami pour lui écrire ou l’inviter dans ton groupe.</p><p>Les membres d’un groupe se retrouvent sur la minimap.</p></div>
        </main>
      </div>
      <div v-else class="friends-group">
        <section v-if="state.groupInvites.length" class="group-invites"><h3>Invitations reçues</h3><article v-for="i in state.groupInvites" :key="i.id" :data-group-invite="i.id"><p><strong>{{ i.fromName }}</strong> t’invite dans son groupe.</p><button :disabled="busy || !connected" data-group-accept @click="answer(i.id,true)">Rejoindre</button><button :disabled="busy || !connected" @click="answer(i.id,false)">Refuser</button></article></section>
        <template v-if="state.group">
          <div class="group-title"><h3>Ton groupe <small>{{ state.group.members.length }} / {{ state.group.limit }}</small></h3><button data-group-leave :disabled="busy || !connected" @click="run('social:groupLeave',{},'Tu as quitté le groupe.')">Quitter le groupe</button></div>
          <p class="group-help">Ta position dans la région est partagée avec ces dresseurs tant que tu restes dans le groupe.</p>
          <ul class="group-members"><li v-for="m in state.group.members" :key="m.id" :data-group-member="m.id"><span class="friend-dot" :class="{online:m.online}"></span><div><strong>{{ m.username }}{{ m.id===userId?' · toi':'' }}</strong><small>{{ m.online?(m.location?locationLabel(m.location):'Connecté'):'Hors ligne' }}{{ m.id===state.group.leaderId?' · Chef du groupe':'' }}</small></div><button v-if="state.group.leaderId===userId&&m.id!==userId" :disabled="busy || !connected" :aria-label="`Retirer ${m.username} du groupe`" @click="run('social:groupKick',{targetId:m.id})">×</button></li></ul>
          <div ref="groupMessages" class="conversation-messages group-messages" role="log" aria-label="Messages du groupe" aria-live="polite"><p v-if="!state.group.messages.length" class="friends-empty">Discute avec ton groupe ici.</p><article v-for="m in state.group.messages" :key="m.id" :class="{mine:m.senderId===userId}"><small>{{ m.senderName }} · {{ time(m.createdAt) }}</small><p>{{ m.text }}</p></article></div>
          <form class="conversation-compose" @submit.prevent="sendGroup"><label class="sr-only" for="group-message">Message au groupe</label><textarea id="group-message" v-model="groupDraft" data-group-draft rows="2" maxlength="500" placeholder="Message au groupe…" :disabled="!connected || sending" @keydown.enter.exact.prevent="sendGroup"></textarea><button data-group-send :disabled="!connected || sending || !groupDraft.trim()">Envoyer</button></form>
        </template>
        <div v-else class="friends-welcome"><h3>Voyager ensemble</h3><p>Invite un ami connecté depuis sa conversation. Il choisira de te rejoindre.</p><p>Jusqu’à six dresseurs peuvent partager leur position sur la minimap.</p></div>
      </div>
    </section>
  </div>
</template>
<script>
import {getMapLocationLabel} from '@/services/mapLocations';
import JournalIcon from '../menu/JournalIcon.vue';
const sortMessages=rows=>[...new Map(rows.map(m=>[m.id,m])).values()].sort((a,b)=>a.id-b.id);
export default {
  components:{JournalIcon},
  props:{tradeInvite:Object,trading:Boolean,canTrade:Boolean,requestTrade:Function,state:{type:Object,required:true},presenceRevision:Number,userId:Number,connected:Boolean,serverError:String,initialTarget:Object,incomingMessage:Object,command:{type:Function,required:true}},
  data:()=>({tab:'friends',query:'',results:[],searching:false,searchMore:false,searchOffset:0,onlineEntries:[],onlineLoading:false,onlineMore:false,onlineOffset:0,onlineTotal:0,selected:null,messages:[],before:null,loadingMessages:false,draft:'',groupDraft:'',busy:false,sending:false,error:'',notice:'',removeConfirmation:false,previousFocus:null}),
  computed:{incomingCount(){return this.state.incoming.length;},sortedFriends(){return [...this.state.accepted].sort((a,b)=>Number(b.online)-Number(a.online)||a.username.localeCompare(b.username,'fr'));},selectedFriend(){return this.state.accepted.find(p=>p.id===this.selected?.id);},selectedOnline(){return this.connected&&(this.selectedFriend?.online??this.selected?.online)===true;}},
  watch:{presenceRevision(){this.refreshDiscovery();},connected(value){if(value)this.refreshDiscovery();else{this._searchVersion=(this._searchVersion||0)+1;this._onlineVersion=(this._onlineVersion||0)+1;clearTimeout(this._searchTimer);clearTimeout(this._onlineTimer);this.results=[];this.onlineEntries=[];this.onlineTotal=0;this.onlineMore=false;this.searchMore=false;this.searching=false;this.onlineLoading=false;}},tab(value){if(value==='online')this.refreshDiscovery();else this.cancelDiscovery();},incomingMessage(m){if(!m||!this.selected||![m.senderId,m.recipientId].includes(this.selected.id))return;this.messages=sortMessages([...this.messages,m]);this.scrollMessages();this.markRead();},'state.group.messages.length'(){this.$nextTick(()=>{const n=this.$refs.groupMessages;if(n)n.scrollTop=n.scrollHeight;});},'state.accepted'(next,previous){if(!this.selected)return;const has=next.some(p=>p.id===this.selected.id),had=previous?.some(p=>p.id===this.selected.id);if(!has){this.messages=[];this.before=null;}else if(!had)this.loadHistory();},initialTarget(p){if(p)this.openTarget(p);}},
  mounted(){this.previousFocus=document.activeElement;this.$refs.close.focus({preventScroll:true});if(this.initialTarget)this.openTarget(this.initialTarget);this._visible=()=>{if(document.visibilityState==='visible')this.markRead();};document.addEventListener('visibilitychange',this._visible);},
  beforeDestroy(){clearTimeout(this._searchTimer);clearTimeout(this._onlineTimer);this._searchVersion=(this._searchVersion||0)+1;this._onlineVersion=(this._onlineVersion||0)+1;this._historyVersion=(this._historyVersion||0)+1;document.removeEventListener('visibilitychange',this._visible);const previous=this.previousFocus;this.$nextTick(()=>{(previous?.isConnected?previous:document.querySelector('.menu-toggle-btn'))?.focus({preventScroll:true});});},
  methods:{
    changeTab(tab){if(this.tab===tab)return;this.selected=null;this.messages=[];this.before=null;this.removeConfirmation=false;this._historyVersion=(this._historyVersion||0)+1;this.tab=tab;},
    openTarget(p){this.changeTab(this.relation(p.id)==='friends'?'friends':'online');return this.selectTrainer(p);},
    cancelDiscovery(){clearTimeout(this._searchTimer);clearTimeout(this._onlineTimer);this._searchVersion=(this._searchVersion||0)+1;this._onlineVersion=(this._onlineVersion||0)+1;this.searching=false;this.onlineLoading=false;},
    async askTrade(){this.error='';try{await this.requestTrade(this.selected.id);}catch(e){this.error=e.message;}},
    relation(id){return [...this.state.accepted,...this.state.incoming,...this.state.outgoing].find(p=>p.id===id)?.relationship||'none';},
    relationshipLabel(r){return{friends:'Amis',incoming:'Demande reçue',outgoing:'Demande envoyée',none:'Vous n’êtes pas encore amis.'}[r];},
    locationLabel(l){const place=getMapLocationLabel(l.nodeId,'fr'),mode={adventure:'Aventure',rift:'Rift',colosseum:'Colosseum'}[l.mode]||'';return `${place} · ${mode}`;},
    time(value){return new Date(value).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'});},
    async run(event,data={},notice=''){if(this.busy)return;this.busy=true;this.error='';this.notice='';try{const result=await this.command(event,data);this.notice=notice;return result;}catch(e){this.error=e.message;}finally{this.busy=false;}},
    async friendAction(id,action){const r=await this.run('social:friend',{targetId:id,action},{request:'Demande envoyée.',accept:'Vous êtes maintenant amis.',decline:'Demande refusée.',cancel:'Demande annulée.',remove:'Ami retiré.'}[action]);if(r){this.removeConfirmation=false;if(action==='accept'&&this.selected?.id===id)await this.loadHistory();}},
    refreshDiscovery(){
      if(!this.connected||this.tab!=='online')return;
      if(this.query.trim().length>=2)this.scheduleSearch();
      clearTimeout(this._onlineTimer);this._onlineVersion=(this._onlineVersion||0)+1;
      this._onlineTimer=setTimeout(()=>this.loadOnline(),180);
    },
    async loadOnline(append=false){
      if(!this.connected||this.tab!=='online')return;
      const version=this._onlineVersion=(this._onlineVersion||0)+1,offset=append?this.onlineOffset:0,targetId=this.selected?.id;
      this.onlineLoading=true;
      try{const r=await this.command('social:online',{offset,...(targetId?{targetId}:{})});if(version!==this._onlineVersion)return;
        this.onlineEntries=[...new Map([...(append?this.onlineEntries:[]),...r.entries].map(p=>[p.id,p])).values()];
        this.onlineMore=Boolean(r.hasMore);this.onlineOffset=offset+20;this.onlineTotal=r.total;if(r.target&&r.target.id===this.selected?.id)this.selected.online=r.target.online;
      }catch(e){if(version===this._onlineVersion)this.error=e.message;}
      finally{if(version===this._onlineVersion)this.onlineLoading=false;}
    },
    scheduleSearch(){
      clearTimeout(this._searchTimer);const query=this.query.trim(),version=this._searchVersion=(this._searchVersion||0)+1;
      this.results=[];this.searchMore=false;this.error='';
      if(query.length<2){this.searching=false;this.loadOnline();return;}
      if(!this.connected||this.tab!=='online'){this.searching=false;return;}
      this.searching=true;this._searchTimer=setTimeout(()=>this.searchPage(query,version,0),300);
    },
    async searchPage(query,version,offset,append=false){
      this.searching=true;
      try{const r=await this.command('social:search',{query,offset});if(version!==this._searchVersion||query!==this.query.trim())return;
        this.results=[...new Map([...(append?this.results:[]),...r.entries].map(p=>[p.id,p])).values()];
        this.searchMore=Boolean(r.hasMore);this.searchOffset=offset+20;const selected=this.results.find(p=>p.id===this.selected?.id);if(selected)this.selected.online=selected.online;
      }catch(e){if(version===this._searchVersion)this.error=e.message;}
      finally{if(version===this._searchVersion)this.searching=false;}
    },
    loadMoreSearch(){if(this.searching||!this.searchMore||!this.connected)return;const version=this._searchVersion=(this._searchVersion||0)+1;return this.searchPage(this.query.trim(),version,this.searchOffset,true);},
    async selectTrainer(p){this.selected={id:p.id,username:p.username,online:p.online===true};this.messages=[];this.before=null;this.draft='';this.error='';this.notice='';this.removeConfirmation=false;if(this.relation(p.id)==='friends')await this.loadHistory();},
    async loadHistory(older=false){const peer=this.selected?.id;if(!peer)return;const version=this._historyVersion=(this._historyVersion||0)+1;this.loadingMessages=true;try{const r=await this.command('social:history',{targetId:peer,...(older&&this.before?{before:this.before}:{})});if(version!==this._historyVersion||this.selected?.id!==peer)return;this.messages=sortMessages([...this.messages,...r.messages]);this.before=r.nextBefore;if(!older){this.scrollMessages();this.markRead();}}catch(e){if(version===this._historyVersion)this.error=e.message;}finally{if(version===this._historyVersion)this.loadingMessages=false;}},
    scrollMessages(){this.$nextTick(()=>{const n=this.$refs.messages;if(n)n.scrollTop=n.scrollHeight;});},
    async markRead(){if(!this.connected||document.visibilityState!=='visible'||!this.selected||this.tab==='group')return;const last=[...this.messages].reverse().find(m=>m.senderId===this.selected.id);if(!last||this._lastRead===`${this.selected.id}:${last.id}`)return;const key=`${this.selected.id}:${last.id}`;try{await this.command('social:read',{targetId:this.selected.id,through:last.id});this._lastRead=key;}catch{/* The unread badge retries when the conversation is reopened. */}},
    async send(){if(this.sending||!this.connected||!this.draft.trim()||!this.selected)return;const peer=this.selected.id,text=this.draft;this.sending=true;this.error='';this.notice='';try{this._pendingMessage=this._pendingMessage?.targetId===peer&&this._pendingMessage.text===text?this._pendingMessage:{targetId:peer,text,clientId:crypto.randomUUID()};const r=await this.command('social:send',this._pendingMessage);this._pendingMessage=null;if(this.selected?.id===peer){this.messages=sortMessages([...this.messages,r.message]);this.draft='';this.scrollMessages();}}catch(e){this.error=e.message;}finally{this.sending=false;}},
    async invite(id){await this.run('social:groupInvite',{targetId:id},'Invitation envoyée. Ton ami peut l’accepter dans l’onglet Groupe.');},
    async answer(inviteId,accept){await this.run('social:groupAnswer',{inviteId,accept});},
    async sendGroup(){if(this.sending||!this.connected||!this.groupDraft.trim())return;this.sending=true;this.error='';this.notice='';try{await this.command('social:groupMessage',{text:this.groupDraft});this.groupDraft='';}catch(e){this.error=e.message;}finally{this.sending=false;}},
    closeOrBack(){if(this.removeConfirmation){this.removeConfirmation=false;return;}if(this.selected&&window.innerWidth<=700){this.selected=null;return;}this.$emit('close');},
    trapFocus(e){const nodes=[...this.$refs.panel.querySelectorAll('button:not(:disabled),input:not(:disabled),textarea:not(:disabled)')].filter(n=>n.getClientRects().length),first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}
  }
};
</script>
<style scoped>
.online-directory{margin-top:18px}.directory-hint{margin:-5px 0 5px;font-size:10px;color:var(--journal-muted)}
.friend-entry .friend-name{display:flex;align-items:center;gap:9px;min-width:0;flex:1;padding-left:0}
.friend-name>span:last-child{min-width:0;overflow-wrap:anywhere}.friend-name small{display:block;color:var(--journal-muted);font-size:10px}
.friend-entry>small{max-width:94px;text-align:right;color:var(--journal-muted);overflow-wrap:anywhere}.directory-more{width:100%;margin-top:10px;font-size:12px}

.friend-trade-invite{padding:10px 16px;background:var(--journal-soft);border-bottom:1px solid var(--journal-border)}.friend-trade-invite p{font-size:12px;margin:0 0 7px}.friend-trade-invite button{font-size:11px;margin-right:6px}.friend-trade-invite small{display:block;color:var(--journal-muted);margin-top:6px}

